//! ⚖️ Original Drawing field equality compares native tree ordinals and UTF8 bytes without cloning payloads.
use semio_framework_pack_json::{ArtifactCanonicalJsonTree as Tree,ArtifactCanonicalJsonNode as Node,ArtifactCanonicalJsonText as Text};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits,close_retained_binding}};
use std::mem::size_of;
#[derive(Clone,Copy,Default)]struct Frame{index:usize,count:usize,object:bool}
pub struct DrawingOriginalEquality{left:Option<RetainedCloneBinding>,right:Option<RetainedCloneBinding>,path:[usize;64],frames:[Frame;64],depth:usize,left_chunk:usize,left_offset:usize,right_chunk:usize,right_offset:usize,phase:u8,result:Option<bool>,closing:bool}
impl Default for DrawingOriginalEquality{fn default()->Self{Self{left:None,right:None,path:[0;64],frames:[Frame::default();64],depth:0,left_chunk:0,left_offset:0,right_chunk:0,right_offset:0,phase:0,result:None,closing:false}}}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Drawing equality original fields changed")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn at<'a>(mut n:&'a dyn Tree,path:&[usize])->Result<&'a dyn Tree,ValueError>{for i in path{n=n.canonical_tree_child(*i)?}Ok(n)}
fn text(n:Node<'_>)->Option<Text<'_>>{match n{Node::String(s)=>Some(Text::Contiguous(s)),Node::Text(s)=>Some(s),_=>None}}
impl DrawingOriginalEquality{
 fn metadata()->usize{2*size_of::<Self>()+2*size_of::<Node<'static>>()}
 pub fn demand<T:Tree>(&self,l:RetainedCloneRef<'_,T>,r:RetainedCloneRef<'_,T>)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if !l.check_binding(&self.left)?{return Ok(fixed(l.binding_copy_bytes()))}if !r.check_binding(&self.right)?{return Ok(fixed(r.binding_copy_bytes()))}Ok(if self.result.is_some(){Default::default()}else{fixed(Self::metadata()+2)})}
 fn reset_text(&mut self){self.left_chunk=0;self.left_offset=0;self.right_chunk=0;self.right_offset=0;}
 fn bytes(&mut self,l:Text<'_>,r:Text<'_>)->Result<(Option<bool>,usize),ValueError>{let l=l.next_byte(&mut self.left_chunk,&mut self.left_offset).map_err(|_|invalid())?;let r=r.next_byte(&mut self.right_chunk,&mut self.right_offset).map_err(|_|invalid())?;let count=usize::from(l.is_some())+usize::from(r.is_some());Ok((match(l,r){(None,None)=>Some(true),(Some(a),Some(b))if a==b=>None,_=>Some(false)},count))}
 pub fn advance<T:Tree>(&mut self,l:RetainedCloneRef<'_,T>,r:RetainedCloneRef<'_,T>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(l,r)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(p)=l.bind(&mut self.left,g)?{return Ok(RetainedCloneStep::Progress(p))}if let Some(p)=r.bind(&mut self.right,g)?{return Ok(RetainedCloneStep::Progress(p))}if self.result.is_some(){return Ok(RetainedCloneStep::Complete(Default::default()))}let mut bytes=0;let result=(||->Result<(),ValueError>{if self.phase==3{if self.depth==0{self.result=Some(true)}else{self.depth-=1;let f=&mut self.frames[self.depth];f.index+=1;if f.index<f.count{self.path[self.depth]=f.index;self.phase=if f.object{1}else{self.depth+=1;0}}}return Ok(())}let a=at(l.get(),&self.path[..self.depth])?;let b=at(r.get(),&self.path[..self.depth])?;if self.phase==1{let f=self.frames[self.depth];let(equal,n)=self.bytes(a.canonical_tree_key(f.index)?,b.canonical_tree_key(f.index)?)?;bytes=n;if let Some(eq)=equal{self.reset_text();if !eq{self.result=Some(false)}else{self.path[self.depth]=f.index;self.depth+=1;self.phase=0}}return Ok(())}let a=a.canonical_tree_node()?;let b=b.canonical_tree_node()?;if self.phase==2{let(equal,n)=self.bytes(text(a).ok_or_else(invalid)?,text(b).ok_or_else(invalid)?)?;bytes=n;if let Some(eq)=equal{self.reset_text();if eq{self.phase=3}else{self.result=Some(false)}}return Ok(())}let same=match(a,b){(Node::Array(a),Node::Array(b))|(Node::Object(a),Node::Object(b))=>{if a!=b{Some(false)}else if a==0{Some(true)}else{if self.depth+1>=64{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"Drawing original equality exceeds native depth"))}let object=matches!(at(l.get(),&self.path[..self.depth])?.canonical_tree_node()?,Node::Object(_));self.frames[self.depth]=Frame{index:0,count:a,object};self.path[self.depth]=0;self.phase=if object{1}else{self.depth+=1;0};None}},(Node::Null,Node::Null)=>Some(true),(Node::Bool(a),Node::Bool(b))=>Some(a==b),(Node::I64(a),Node::I64(b))|(Node::I64Text(a),Node::I64Text(b))=>Some(a==b),(Node::U64(a),Node::U64(b))|(Node::U64Text(a),Node::U64Text(b))=>Some(a==b),(Node::I128(a),Node::I128(b))=>Some(a==b),(Node::U128(a),Node::U128(b))=>Some(a==b),(Node::F32(a),Node::F32(b))=>Some(a==b),(Node::F32HexWord(a),Node::F32HexWord(b))=>Some(a.to_bits()==b.to_bits()),(Node::F64(a),Node::F64(b))=>Some(a==b),(a,b)=>if text(a).is_some()&&text(b).is_some(){self.phase=2;None}else{Some(false)}};if let Some(eq)=same{if eq{self.phase=3}else{self.result=Some(false)}}Ok(())})();let p=RetainedCloneProgress{copied_items:1,copied_bytes:Self::metadata()+bytes,..Default::default()};result.map_err(|e|e.with_retained_progress(p))?;Ok(if self.result.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn result(&self)->Option<bool>{self.result}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.left.is_some(){RetainedCloneBinding::close_demand(&self.left,body)}else{RetainedCloneBinding::close_demand(&self.right,body)}}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid())}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.left.is_some(){return close_retained_binding(&mut self.left,g).map(|s|RetainedCloneStep::Progress(s.progress()))}close_retained_binding(&mut self.right,g)}
 pub fn terminal_is_empty(&self)->bool{self.left.is_none()&&self.right.is_none()}
}
impl Drop for DrawingOriginalEquality{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Drawing original equality retains native field sources");}}

